                     ['Envolvente [mín; máx] (±0,5 m en el borde)', '[{app_g1_env4_min}; {app_g1_env4_max}]', '[{app_g2_env4_min}; {app_g2_env4_max}]', '[{app_env4_min}; {app_env4_max}]'],
